"use strict";
  function firmCard(f){return `<article class="result-card"><div><span class="owner-label">Firms owner</span><h3>${esc(f.name)}</h3><p>${esc(f.description)}</p><div class="result-meta">${statusBadge(f.status)}<span>${esc(f.category)}</span><span>${esc(f.city)}</span>${f.expanded?`<span class="badge badge-blue">Разширен профил</span>`:""}${f.admin?`<span class="badge badge-dark">Admin / Ivanov</span>`:""}</div></div><div class="result-actions"><button class="button button-soft" type="button" data-route="firm/${f.id}">Виж профила</button></div></article>`}
  function renderFirms(){main.innerHTML=pageIntro("Постоянни профили","Фирми","Постоянният фирмен профил е различен от временната обява.",button("Добави фирма","firm-form","button button-primary"))+`<section class="section"><div class="shell"><div class="toolbar"><input class="toolbar-search" id="firm-search" type="search" placeholder="Търси фирма или категория"><div class="segmented"><button class="active" data-firm-category="all">Всички</button><button data-firm-category="Строителство и ремонти">Ремонти</button><button data-firm-category="Автомобили">Автомобили</button><button data-firm-category="Заведения">Заведения</button></div></div><div id="firm-results">${stateGate(`<div class="result-list">${[...D.firms].sort((a,b)=>Number(b.admin)-Number(a.admin)).map(firmCard).join("")}</div>`,"Все още няма фирми.")}</div></div></section>`}
  function renderFirmDetail(id){const f=D.firms.find(x=>x.id===id);if(!f)return renderNotFound();main.innerHTML=pageIntro("Фирма",f.name,f.category,`<button class="button button-primary" type="button" data-action="call" data-phone="${esc(f.phone)}">Обади се</button>`+`<button class="button button-soft" type="button" data-share="firm/${f.id}" data-share-title="${esc(f.name)}">Сподели</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Фирми","firms"],[f.name,""]])}<div class="detail-title"><div class="flex">${statusBadge(f.status)}${f.expanded?`<span class="badge badge-blue">Разширен профил</span>`:""}</div><h1>${esc(f.name)}</h1><p>${esc(f.description)}</p></div>${f.expanded?`<div class="detail-block"><h2>Услуги</h2><div class="tag-row">${(f.services||[]).map(x=>`<span class="badge badge-blue">${esc(x)}</span>`).join("")}</div></div><div class="detail-block"><h2>Район на работа</h2><p>${esc(f.area||f.city)}</p></div>`:""}<div class="detail-block"><h2>Галерия</h2><div class="photo-preview">${Array.from({length:6},(_,i)=>`<span>Снимка ${i+1}</span>`).join("")}</div></div>${f.expanded?`<div class="detail-block"><h2>Преди и след</h2><div class="grid grid-2"><div class="notice"><strong>Преди</strong>Прототипно място за снимка преди ремонта.</div><div class="notice notice-ok"><strong>След</strong>Прототипно място за завършения резултат.</div></div><p class="muted small">В основните правила тази секция е част от целевия ред на разширения профил; реалният write flow остава отделна следваща техническа задача.</p></div>`:""}<div class="detail-block"><h2>Контакти и работно време</h2><div class="facts"><div class="fact"><span>Телефон</span><strong>${esc(f.phone)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(f.address||"Не е посочен")}</strong></div><div class="fact"><span>Работно време</span><strong>${esc(f.hours||"Не е посочено")}</strong></div>${f.website?`<div class="fact"><span>Сайт</span><strong>${esc(f.website)}</strong></div>`:""}</div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" type="button" data-action="call" data-phone="${esc(f.phone)}">Обади се</button><button class="button button-outline" type="button" data-route="offer-request?firm=${f.id}">Поискай оферта</button>${f.website?`<button class="button button-outline" type="button" data-action="website" data-url="https://${esc(f.website)}">Сайт</button>`:""}<button class="button button-outline" type="button" data-share="firm/${f.id}" data-share-title="${esc(f.name)}">Сподели</button><button class="button button-outline" type="button" data-route="report?target=${encodeURIComponent(f.name)}&owner=firm">Докладвай</button><button class="button button-soft" type="button" data-route="firm-form?edit=${f.id}">Редактирай (прототип)</button></div></aside></div></section>`}
  function renderFirmForm(){const r=routeInfo(),editId=r.params.get("edit"),f=editId?D.firms.find(x=>x.id===editId):null;main.innerHTML=pageIntro("Firms owner",f?"Редактирай фирма":"Добави фирма",f?"Последната одобрена публична версия остава видима, докато редакцията чака преглед.":"Създай основен постоянен профил. Нормалният потребител изпраща за преглед.")+`<section class="section"><div class="shell form-wrap"><div class="form-card">${!isAdmin()?`<div class="notice notice-info"><strong>${isModerator()?"Moderator — собствена фирма":"Публикуване след преглед"}</strong>${isModerator()?"Собствената фирма на Moderator е normal firm — без direct publish и без Admin права.":"Новата фирма не става публична преди одобрение."}</div>`:`<div class="notice notice-ok"><strong>Admin режим</strong>Direct publish и защитен expanded access според съществуващите правила.</div>`}<form class="form-grid proto-form mt-16" data-form="firm" data-edit-id="${esc(editId||"")}">${field("Име на фирмата","name",{required:true,min:2,value:f?.name||""})}${selectField("Категория","category",["Строителство и ремонти","Автомобили","Професионални услуги","Заведения","Красота","Дом и градина","Друго"],f?.category||"",{required:true})}${field("Телефон","phone",{required:true,type:"tel",value:f?.phone||""})}${field("Град (по желание)","city",{value:f?.city||"Лом"})}${field("Адрес (по желание)","address",{value:f?.address||""})}${field("Работно време (по желание)","hours",{value:f?.hours||""})}${field("Описание","description",{textarea:true,required:true,min:20,full:true,value:f?.description||""})}<div class="field field-full"><label>Лого (по желание)</label><div class="photo-drop"><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"><strong>1 лого</strong><br><small>JPG, PNG или WebP. Не се качва реално.</small></div></div><div class="field field-full"><label>Снимки на обекти и услуги</label><div class="photo-drop"><input type="file" name="gallery" accept="image/jpeg,image/png,image/webp" multiple><strong>До 6 снимки за normal firm flow</strong></div></div>${isAdmin()?`<div class="form-section"><h3>Admin-only: Разширен профил</h3><p class="muted">Дава се/отнема само от Admin. Не се появява като право за normal user или Moderator.</p>${field("Кратко представяне","short_intro",{textarea:true,full:true})}${field("Сайт","website",{type:"url",full:true})}${field("Услуги — по една на ред","services",{textarea:true,full:true})}${field("Район на работа","service_area",{textarea:true,full:true})}${field("Работно време — разширено","expanded_hours",{textarea:true,full:true})}<div class="grid grid-2"><label class="check-row"><input type="checkbox" name="show_intro"> Покажи представянето</label><label class="check-row"><input type="checkbox" name="show_site"> Покажи бутона „Сайт"</label><label class="check-row"><input type="checkbox" name="show_services"> Покажи услугите</label><label class="check-row"><input type="checkbox" name="show_area"> Покажи района</label></div></div>`:""}<div class="form-actions"><button class="button button-outline" type="button" data-route="firms">Отказ</button><button class="button button-primary" type="submit">${isAdmin()?"Запази и публикувай":f?"Запази и изпрати за преглед":"Изпрати за преглед"}</button></div></form></div></div></section>`;bindFormUX()}
  function renderRestaurants(){const rows=D.firms.filter(x=>x.category==="Заведения");main.innerHTML=pageIntro("Открий в Лом","Заведения и храна","Това е специализиран discovery изглед, но owner-ът остава Firms.",button("Виж всички фирми","firms"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Един owner</strong>Ресторантът е фирмен профил, не отделен database тип и не отделна форма.</div><div class="result-list mt-16">${rows.map(firmCard).join("")}</div></div></section>`}

  function shopCard(s){return `<article class="result-card"><div><span class="owner-label">Shops owner</span><h3>${esc(s.name)}</h3><p>${esc(s.category)} · ${esc(s.address)}</p><div class="tag-row">${s.tags.map(t=>`<span class="badge">${esc(t)}</span>`).join("")}</div></div><div class="result-actions"><button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button><button class="button button-soft" data-route="shop/${s.id}">Детайли</button></div></article>`}
  function renderShops(){const cats=["Всички","Хранителни","Строителни","Техника","Мебели","Дрехи","Дом"];main.innerHTML=pageIntro("Открий в Лом","Магазини","Специализиран Shops owner с отделно предложение за нов магазин.",button("Предложи магазин","shop-proposal","button button-primary"))+`<section class="section"><div class="shell"><div class="toolbar"><input id="shop-search" class="toolbar-search" type="search" placeholder="Търси магазин, адрес или какво предлага"><div class="segmented">${cats.map((c,i)=>`<button class="${i===0?"active":""}" data-shop-category="${esc(c)}">${esc(c)}</button>`).join("")}</div></div><div id="shop-results">${stateGate(`<div class="result-list">${D.shops.map(shopCard).join("")}</div>`,"Все още няма одобрени магазини.")}</div></div></section>`}
  function renderShopDetail(id){const s=D.shops.find(x=>x.id===id);if(!s)return renderNotFound();main.innerHTML=pageIntro("Магазин",s.name,s.category,`<button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button>`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Магазини","shops"],[s.name,""]])}<div class="detail-block"><h2>Информация</h2><div class="facts"><div class="fact"><span>Категория</span><strong>${esc(s.category)}</strong></div><div class="fact"><span>Адрес</span><strong>${esc(s.address)}</strong></div><div class="fact"><span>Работно време</span><strong>${esc(s.hours)}</strong></div><div class="fact"><span>Телефон</span><strong>${esc(s.phone)}</strong></div></div><div class="tag-row">${s.tags.map(t=>`<span class="badge badge-blue">${esc(t)}</span>`).join("")}</div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-action="call" data-phone="${esc(s.phone)}">Обади се</button><button class="button button-outline" data-share="shop/${s.id}" data-share-title="${esc(s.name)}">Сподели</button><button class="button button-outline" data-route="report?target=${encodeURIComponent(s.name)}&owner=shop">Докладвай</button></div></aside></div></section>`}
  function renderShopProposal(){main.innerHTML=pageIntro("Shops owner","Предложи магазин","Отделна Shop-owned форма. Не се преобразува в „Добави фирма“.")+`<section class="section"><div class="shell form-wrap"><div class="form-card"><div class="notice notice-info"><strong>Изисква вход</strong>Предложението се изпраща за проверка и не е публично веднага.</div><form class="form-grid proto-form mt-16" data-form="shop-proposal">${field("Име на магазина","name",{required:true,min:2})}${selectField("Категория","category",["Хранителни","Строителни","Техника","Мебели","Дрехи","Дом"],"",{required:true})}${field("Телефон","phone",{required:true,type:"tel"})}${field("Адрес","address",{required:true,min:3})}${field("Работно време","hours",{})}${field("Какво предлага","offer",{textarea:true,required:true,min:15,full:true,placeholder:"Кратко и конкретно описание"})}${field("Уточнения / тагове","tags",{full:true,placeholder:"напр. Бои, инструменти, санитария"})}${field("Източник / откъде знаеш","source",{textarea:true,full:true,placeholder:"По желание — сайт, табела, личен контакт"})}<div class="form-actions"><button class="button button-outline" type="button" data-route="shops">Отказ</button><button class="button button-primary" type="submit">Изпрати за проверка</button></div></form></div></div></section>`;bindFormUX()}

  function eventCard(e){return `<article class="result-card"><div><span class="owner-label">Events owner</span><h3>${esc(e.title)}</h3><p>${esc(e.date)} · ${esc(e.time)} · ${esc(e.place)}</p><div class="result-meta">${statusBadge(e.status)}</div></div><div class="result-actions"><button class="button button-soft" data-route="event/${e.id}">Виж събитието</button></div></article>`}
  function renderEvents(){main.innerHTML=pageIntro("Открий в Лом","Събития","Показват се одобрени текущи и предстоящи събития. Публична Add Event форма не е измислена.",button("Попитай за събитие","ask?category=Събития","button button-primary"))+`<section class="section"><div class="shell"><div class="notice notice-info"><strong>Read-only owner в първоначалния V6</strong>Има „Разгледай събития“ и „Попитай за събитие“, но няма фалшив бутон „Добави събитие“.</div><div class="mt-16">${stateGate(`<div class="result-list">${D.events.map(eventCard).join("")}</div>`,"В момента няма предстоящи одобрени събития.")}</div></div></section>`}
  function renderEventDetail(id){const e=D.events.find(x=>x.id===id);if(!e)return renderNotFound();main.innerHTML=pageIntro("Събитие",e.title,`${e.date} · ${e.time} · ${e.place}`)+`<section class="section"><div class="shell detail-layout"><div class="detail-main">${crumb([["Събития","events"],[e.title,""]])}<div class="detail-block"><h2>За събитието</h2><p>${esc(e.description)}</p><div class="facts"><div class="fact"><span>Дата</span><strong>${esc(e.date)}</strong></div><div class="fact"><span>Час</span><strong>${esc(e.time)}</strong></div><div class="fact"><span>Място</span><strong>${esc(e.place)}</strong></div></div></div></div><aside class="detail-side"><div class="detail-block detail-actions"><button class="button button-primary" data-share="event/${e.id}" data-share-title="${esc(e.title)}">Сподели</button><button class="button button-outline" data-route="ask?category=Събития&q=${encodeURIComponent(e.title)}">Попитай</button><button class="button button-outline" data-route="report?target=${encodeURIComponent(e.title)}&owner=event">Докладвай</button></div></aside></div></section>`}
